INSERT INTO `w_bo_xs_projectmanage` VALUES ('2056239333215526914', '0', '0', '16466317325076496', '梁皓', '2026-05-18 13:03:55', '16466317325076496', '梁皓', '2026-05-18 18:25:23', '1', '2056239333563682818', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '2', 'XMBM202605180021', '1', '明确需求', '欣满和--寐岚、凝思仿香修改2-0260518', '2056233997431693314', '天津欣满和生物科技有限公司', '根据客户提供标样进行芳香修改\n凝思精油配方：人参、白茯苓、远志、沉香、甜橙、茉莉、薄荷\n寐岚精油配方：酸枣仁、远志、玫瑰、苦橙花、绿萼梅、肉桂\n做香精仿香\n凝思仿香相似度高\n寐岚在原本的仿香上增加竹叶联想主题\n产品为香薰\n价格300~500\n需求时间：6.3', '1', '4', 'C级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '1', '高', NULL, NULL, NULL, '0', '否', '2', '微变', NULL, '', '', '', '', '4', '中国化妆品INCI', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, NULL, NULL, '2027-05-31 00:00:00', '300~500', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2056242808708096001', '0', '0', '16466317325076496', '梁皓', '2026-05-18 13:17:43', '16466317325076496', '梁皓', '2026-05-19 13:43:54', '1', '2056242808867508226', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '2', 'XMBM202605180022', '1', '明确需求', '培蘑--百香果创香20260518', '2056240209187528706', '培蘑（上海）贸易有限公司', '冷先生项目\nSYP2043DSY 百香果香基\n调香师：刘扬\n1.加入多汁、精纯的果香状态。\n百香果香基未经稀释的状态是最好的，果香饱满，目前果香的状态比较偏平，经过多轮普通消费者测试，大家反馈平平。增\n加多汁意向可在前调迅速抓住鼻子。\n2.降糖\n百香果被Pape Moe定位为热卖选题（同草莓、芭乐）为了更好的销量希望适当降低甜度，去适配更多的中国消费者。\n3.多样的搭配增加耐闻度，与市面上单一果香品牌拉开距离\n我们提出一些搭配思路供调香师参考\nA.焚香+百香果\n轻盈的日式焚香与百香果的热情碰撞\nB.草本+百香果\n罗勒、尤加利、薄荷、斑斓一些比较受欢迎的草本都可以尝试。\nC.辛香+百香果\n一些比较芳香偏绿的辛香，芫荽、黑胡椒、小豆蔻、月桂叶等等\n\n需要根据客户需求提供3个方向递样\nSYP2043DSY 百香果香基整体减低甜感，增加热带果感\n该项目指定调香师：刘扬\n1、焚香+百香果\n2、草本+百香果\n3、辛香+百香果\n\n需求价格：2000以内\n需要15%香水加香产品\n需求时间：6.5寄出', '3', '1', 'S级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '1', '是', '1', '高', NULL, '丰富度、层次感', NULL, '1', '是', '2', '微变', '客户确定后进行，高低温、紫外光照', '', '', '2', '无要求', '4', '中国化妆品INCI', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, '81过敏原，香水加香量暂定20%后续会与客户确认，有出口需求', NULL, '2027-05-31 00:00:00', '2000以内', '15', NULL, NULL, NULL, NULL);
