INSERT INTO `w_bo_xs_projectmanage` VALUES ('2062367751946592257', '0', '0', '17400514601408872', '于姗姗', '2026-06-04 10:56:04', '17400514601408872', '于姗姗', '2026-06-04 10:56:04', '1', '2062367752135278593', 'SUCCESS_END', '成功结束', '1009466484', '销售服务部', '1', 'XMBM202606040005', '1', '明确需求', '元嘉 -DXF2039BDX修改配方-20260604-不邮寄', '1985593757239496706', '元嘉母婴用品股份有限公司', '价格不变 去变色\n0.5%添加量\n做成无色液体香精\n用途洗衣液\n不邮寄', '20', '3', 'B级项目', '0549274114954944,17400514601408872', '王鑫,于姗姗', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-06-04 00:00:00', '-', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2062368414218805249', '0', '0', '17127345845433575', '王晔', '2026-06-04 10:58:42', '05035817329389', '刘畅', '2026-06-04 11:22:26', '1', '2062368414373937154', 'SUCCESS_END', '成功结束', '156706111', '市场部', '2', 'XMBM202606040006', '1', '明确需求', '泰国咖啡店创香', '2062367275544961026', 'Uthen', 'SERIES 01: FLOW STATE\nConcept: Focus, immersion, ritual, quiet power\nTrend alignment accords:\n•	Incense\n•	Woody \n•	Herb\nOlfactive Direction:\nWoody × Herbal × Incense (but modern, soft, meditative—not heavy temple smoke)\nSignature Structure:\n•	Top Notes (Entry / Breath): \no	Clary Sage \no	Green Tea \no	Eucalyptus Mist \n•	Heart Notes (Focus / Flow): \no	Palo Santo \no	Lavender Absolute \no	Rosemary Smoke \n•	Base Notes (Grounding / Depth): \no	Sandalwood (creamy, soft) \no	Vetiver (clean earth) \no	White Incense / Frankincense Resin \nVariations (Sub-SKU ideas):\n•	Silent Wood → more sandalwood + skin musk \n•	Ritual Smoke → deeper incense + myrrh \n•	Green Focus → herbal-forward (tea + sage) \nPositioning Language:\n“A scent that slows time. Warm wood, quiet smoke, and green breath — designed for clarity.”\n\nSERIES 02: DRUNK\nConcept: Playful, addictive, nightlife, blurred edges\nTrend alignment accords:\n•	Gourmand + food-inspired scents are evolving into complex, mature blends \n•	Cocktail / fruity notes are trending but paired with depth (woods, musk) \n•	Experimental, provocative scent storytelling is rising \nOlfactive Direction:\nCocktail × Sweet × Boozy × Textural\nSignature Structure:\n•	Top Notes (First Sip): \no	Rum / Cognac Accord \no	Cherry / Dark Berry \no	Citrus Zest (orange peel / yuzu) \n•	Heart Notes (Buzz): \no	Espresso Shot / Coffee Foam \no	Caramelized Sugar \no	Spiced Cinnamon / Nutmeg \n•	Base Notes (Aftertaste): \no	Tonka Bean \no	Vanilla Smoke \no	Oak Barrel / Whisky Wood \nVariations:\n•	Espresso Martini → coffee + vodka + vanilla \n•	Cherry Highball → cherry + sparkling citrus + musk \n•	Burnt Sugar Night → caramel + rum + smoky wood \nPositioning Language:\n“Not a drink. A feeling. Sweet, dark, addictive — the scent of losing control.”\n\nSERIES 03: AWARENESS\nConcept: Presence, lightness, clarity, awakening\nTrend alignment accord:\n•	“Skin scents” and subtle fragrances are trending \n•	Fresh scents are becoming more airy, mineral, and modern \n•	Consumers want lighter, everyday wearable scents \nOlfactive Direction:\nFresh × Bright × Clean × Minimal\nSignature Structure:\n•	Top Notes (Awakening): \no	Bergamot \no	Lemon Leaf \no	Green Apple \n•	Heart Notes (Clarity): \no	White Tea \no	Neroli \no	Water Lily / Aquatic Accord \n•	Base Notes (Soft Presence): \no	Clean Musk \no	Light Cedarwood \no	Mineral / Skin Accord \nVariations:\n•	Morning Air → citrus + tea + light musk \n•	Skin Light → minimal musk + soft wood \n•	Ocean Mind → aquatic + mineral + citrus \n\nPositioning Language:\n“Barely there. But everything changes. A scent that feels like being awake.”\n\nFINAL BRAND FEEL (reference)\nThis collection will feel like:\n•	Flow State → Aesop × Zen \n•	Drunk → Byredo × Nightlife \n•	Awareness → Le Labo × Clean Air', '1', '1', 'S级项目', '16466317325076496', '梁皓', '05035817329389', '刘畅', '[{\"fileName\":\"Perfume Concept for our next branding.docx\",\"timestamp\":\"AKsXKj4878Ndmxbhq8tz\",\"size\":19557,\"secret\":null,\"fileId\":\"574fe8f0-cd42-45ca-97fd-1d80ff3bb904\",\"showSize\":\"19KB\",\"fileClass\":\"iconBox wordBox\"}]', '•	Flow State → Aesop × Zen  •	Drunk → Byredo × Nightlife  •	Awareness → Le Labo × Clean Air', NULL, NULL, NULL, '1', '是', '', '', 'EDP加香20%', NULL, NULL, '1', '是', '2', '微变', NULL, '', '', '', '', '', '', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, NULL, NULL, '2026-08-31 00:00:00', '不限', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2062371602770649089', '0', '0', '17127345845433575', '王晔', '2026-06-04 11:11:22', '17127345845433575', '王晔', '2026-06-04 11:11:22', '1', '2062371603001278466', 'SUCCESS_END', '成功结束', '156706111', '市场部', '1', 'XMBM202606040007', '1', '明确需求', '仙迪刷酸清爽沐浴慕斯', '1985593758309044225', '广州市仙迪生物科技有限公司', '沐浴慕斯，然后主打一个刷酸刷酶，然后去掉身上鸡皮的这个概念。然后希望在夏天比较热的时候去主推，所以这个味道要相对比较清新比较清爽，然后有一点带酸味，然后有一种雨后的这种苔藓的这种留香\n清爽、自然、舒适\n1）普宁的青梅-酸酸的雨后苔藓\n2）牛油果\n3）其他方向杨桃、白葡萄酒', '5', '1', 'S级项目', '1638968357988946', '何家文', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '1', '是', '', '', NULL, '', '', '', '', '', '', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, NULL, NULL, '2026-12-31 00:00:00', '待确认', NULL, NULL, NULL, NULL, NULL);
