INSERT INTO `w_bo_xs_projectmanage` VALUES ('2069272444278919170', '0', '0', '05035817437137', '宣二鹏', '2026-06-23 12:12:51', '17400514601408872', '于姗姗', '2026-06-23 13:33:16', '1', '2069272444471853058', 'SUCCESS_END', '成功结束', '12377314', 'DHFF', '2', 'XMBM202606230007', '1', '明确需求', '锦意-微胶囊仿香项目20260623', '1984130168527933442', '陕西锦意日化有限公司', '项目情况：\n1.仿香项目\n2.微胶囊项目\n3.价格60元/公斤\n4.采购量每次2吨，每月一次。\n5.香精10克。\n弄好了邮寄给幸', '50', '3', 'B级项目', '17400514601408872,05035817437137', '于姗姗,宣二鹏', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '1', '是', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-06-22 00:00:00', '60元/公斤', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2069333851070517249', '0', '0', '16466317325076496', '梁皓', '2026-06-23 16:16:51', '113845370124130976', '彭佳庆', '2026-06-23 16:29:10', '1', '2069333851280228353', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '2', 'XMBM202606230009', '1', '明确需求', '星宇昊海--新品蜡烛推荐&修改20260623', '1984130169933025282', '上海星宇昊海文化传媒有限责任公司', '1.  蜜瓜+微量的葡萄（不想有化工感）+玫瑰。\n蜜瓜推荐：LYP485ALY、JKC1246DJK、LJC1226BLJ\n\n 2.苔洇碧染，你试试看再给我的两个苔藓味道里，加点青草和雨后泥土的味道吧，现在没有雨后的感觉，只有凉意，没有水汽和湿气。     \n苔藓推荐：LCC1236ALC、LYP1504ALY\n番茄叶推荐：LYC2065ALY、LYC2065ALY、LYP1142BLY\n\n3.  馕与核桃：新疆美食调\n核桃香型推荐：LJP1190ALJ\n\n4.  胡杨红柳： 模拟意象中的胡杨和红柳的味道吧。        大漠苍凉感的木质调+顽强的生命力的感觉（就是干燥中又带着点清新感，类似沙漠绿洲的感觉 ）\n胡杨红柳：LYP2375BLY\n\n5. 生生不息：水润生瓜+竹笋+青涩瓜藤+大地，或者加点之前的松针的味道+藤（那种有点青涩的藤，，加青草或者菊花的那个味道？），  松柏+岩兰草+苔藓+荷花\n瓜香推荐：LYP1555ALY\n\n6. 秦简汉牍：药感墨香木质调（少量的香芒+少量花椒；松烟墨（如何实现？松焦油，松香油？  ）+麝香+丁香；  干燥木质调（柏木、创愈木可以带一点淡淡的干竹子香）\n秦简汉牍：LYP735ALY、LYP1159BLY\n竹香：LYP1652ALY\n\n7. 苍松翠柏  松木+柏树 松针+柏叶 加点松果 松子的味道，也是木质调。\n松针推荐：LYP1468BLY\n优先提供有库存版本\n产品用于蜡烛产品内\n需求价格：500以内\n先推荐香型确认后需要修改\n需求时间：6.26\n寄样地址：上海市黄浦区淮海中路 627号WeWork 4F， 18117207858 李俊', '1', '4', 'C级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '2', '无要求', '4', '中国化妆品INCI', '4,3,2', 'COA,SDS,IFRA', NULL, NULL, NULL, NULL, '2027-06-30 00:00:00', '500以内', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2069352132498149378', '0', '0', '16466317325076496', '梁皓', '2026-06-23 17:29:30', '16466317325076496', '梁皓', '2026-06-23 17:29:30', '1', '2069352132720443394', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202606230010', '1', '明确需求', '回家本能--植物系列主题新品推荐&修改20260623', '1984130174383181825', '橘正义（宁波）化妆品有限公司', 'Eddy收\n根据客户提供brief进行第一批推荐后续根据需求进行优化修改\n1、发财树 · MONEY TREE\n前调：鸢尾根、纸莎草、干燥琥珀\n中调：乳香、没药、龙涎香醚\n后调：雪松、檀木、开司米木\n推荐：LYP735ALY、YQP092AYQ、LCP866ALC\n\n2、桃花灼灼\n前调：桃花、杏子\n中调：白桃、番茄叶、玫瑰、茉莉\n后调：青草、桃叶、橡木苔\n推荐：黑宫桃花，需要调香师根据已有GC谱图仿香提供\n\n3、红菜头 · GARDEN RADISH\n前调：湿润泥土、胡萝卜籽、青绿根茎\n中调：甜菜汁、红浆果、紫罗兰叶\n后调：香根草、雪松、白麝香\n推荐：DHA2030ADH、LYP636BLY\n\n4、椰子树 · COCONUT PALM\n前调：青椰子水、海盐、柠檬草\n中调：椰肉、绿叶、鸡蛋花\n后调：浮木、白麝香、檀香\n推荐：LJP565ALJ、SYP968BSY\n\n5、小葵 · SUN FLOWER\n前调：青绿茎叶、柠檬、佛手柑\n中调：向日葵花、橙花、蜂蜜\n后调：香草、白麝香、葵花籽\n推荐：LYP928BLY、LYP926ALY、LYP1681BLY、LYA2274ALY、LYP883BLY\n\n客户产品用于香珠、香氛喷雾\n需求价格：400以内\n需求时间：6.26\n第一波推荐为参考香气，只需寄香精即可\n后续正式修改样品需要15%香水加香产品', '3', '4', 'C级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '17253690046572896', '周宇', '[{\"fileName\":\"新款植物香型开发.pdf\",\"timestamp\":\"wATpaSBV4EYM30eOHWom\",\"size\":1006034,\"secret\":null,\"fileId\":\"9c3444ac-688f-436c-afc1-66f8ba99c2ae\",\"showSize\":\"982KB\",\"fileClass\":\"iconBox pdfBox\"}]', NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '2', '无要求', '4', '中国化妆品INCI', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, '客户确认后提供需要81过敏原', NULL, '2027-06-30 00:00:00', '400以内', NULL, NULL, NULL, NULL, NULL);
