INSERT INTO `w_bo_xs_projectmanage` VALUES ('2070040967846547457', '0', '0', '16466317325076496', '梁皓', '2026-06-25 15:06:41', '16466317325076496', '梁皓', '2026-06-25 15:06:41', '1', '2070040968068841474', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202606250012', '1', '明确需求', '半酣--个护&家具香氛需求推荐20260625', '2070036268950999042', '上海柏凯恩贸易有限公司', '半酣收\n根据客户线下拜访选中样品进行推荐\nLYP2375BLY	柳叶与琥珀  需要寄样10g\nSYP2507BSY 单一麦芽  需要寄样10g\nLJP2468BLJ	紫罗兰30  需要寄样10g\nLYP2386BLY	化蝶女士43  需要寄样10g\nLYP1678BLY 香柠檬22  需要寄样30g（该款客户需要用于个护与无火产品内）\nLYP1526ALY  绿豆沙（蜡烛）需要寄样10g\n\n需求时间：6.29\n需求价格：400以内\nLYP1526ALY 绿豆沙需要10%蜡烛加香产品\nLYP1678BLY 香柠檬22需要10%无火加香产品，溶剂为MMB', '1', '4', 'C级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '2', '无要求', '4', '中国化妆品INCI', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, '客户确样后提供', NULL, '2027-06-30 00:00:00', '400以内', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2070042632565805058', '0', '0', '02461210300720808373', '余鹏程', '2026-06-25 15:13:18', '02461210300720808373', '余鹏程', '2026-06-25 15:28:57', '1', '2070042632762933250', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '2', 'XMBM202606250013', '1', '明确需求', '（非常紧急）沃德绿精油产品调整-提振 26-06-25', '2038526979971465218', '南京宝生源食品有限公司', '原版本：DH-A27729 提振精油（改版4#） LQP2055ALQ\n现客户根据出口国当地法规要求，对配方调整有新需求，具体内容如下：\n药剂师审查了所提供的原料IFRA证书（第51号修正案），并从中识别出两种次要成分，需对其浓度进行调整，以确保符合拉丁美洲各国的法规要求（依据安第斯共同体第833号决定）：\n1) 佛手柑果油（成分编号4）： 要求将其浓度设定为1.500%（重量/重量），以安全地符合相关限制要求，并降低与呋喃香豆素相关的风险。此外，我们要求该工厂以书面形式更正/确认，该批佛手柑油不含呋喃香豆素（FCF / furocoumarin-free）。\n2)亚香茅（CYMBOPOGON NARDUS）油： CYMBOPOGON NARDUS OIL（成分编号11）： 要求将其浓度从0.10%降至0.050%（百分比），以使产品符合IFRA第3类（指尖留置式应用）的严格限值（最高允许浓度为0.07222%），从而确保产品符合相关规定。 为了在不改变活性成分混合物的感官特性及功能性的前提下，将质量平衡精确维持在100.00%，\n建议将总减量（0.275%（p/p））通过增加主要成分（甜杏仁油）的含量来弥补，将其比例从85%提高至85.275%。 附上配方第3版修订稿，供与制造商进行验证管理之用。\n\n******样品中文名可取《清新精油3.0》，样品需20g，完成后可直接寄给上海有息，并需要我司出具“不含呋喃香豆素”盖章声明\n有息收货地址：上海市闵行区华宁路3333号海联智谷科创产业园28号楼4楼任兰兰13262964371', '1', '2', 'A级项目', '02461210300720808373', '余鹏程', '05035817329389', '刘畅', '[{\"fileName\":\"Formula QQ-Breathe Blend Essential Oils.Rev3.24062026.xlsx\",\"timestamp\":\"TnPsjbRi1WL4fpzDzibF\",\"size\":15605,\"secret\":null,\"fileId\":\"e260fed3-98c9-495b-bf02-534305d8f7f9\",\"showSize\":\"15KB\",\"fileClass\":\"iconBox excelBox\"}]', NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-06-25 00:00:00', '2000', NULL, NULL, NULL, NULL, NULL);
