INSERT INTO `w_bo_xs_projectmanage` VALUES ('2072882638380584962', '0', '0', '1638968357988946', '何家文', '2026-07-03 11:18:28', '1638968357988946', '何家文', '2026-07-03 11:18:28', '1', '2072882638611267585', 'SUCCESS_END', '成功结束', '1055369916', '日化2组（南区）', '1', 'XMBM202607030004', '1', '明确需求', '戈海（屈臣氏）  DH-G812355--DXB2539ADX粉韵樱花  版本修改', '1984130167739404290', '广州戈海贸易有限公司', 'DH-G812355--DXB2539ADX粉韵樱花 分别用于精华油水相、精华油油相、修颜防晒霜和焕活防晒霜，一共4款产品；\n客户反馈：现在客户反馈两款精华油产品中的香精加在“油相”基体后就出现变蒙，两款防晒霜添加香精都会出现香精气味与防晒剂气味分层的情况（香精压不住防晒剂味道，但是也有香精气味冒出）；\n修改需求：均使用客户提供的基料进行调配和做加香测试\n1、两款香精都要做成亲油版本，溶于基体不浑浊，香精符合法规不含屈臣氏禁用物质（禁用物质在附件）；\n2、水相和油相精华油，油/水/香精的比例为：13%油+87%水+0.2%的香精，就是0.2g的油加在13G的油里，正常工艺操作是香精加到油相，然后油相再倒入水相使用前摇晃均匀即可，所以需要把香精修改成在油相中不浑浊变蒙；\n3、两款防晒霜，香精添加量0.3%，修改后香精能盖住基料的味道，不出现气味分层，尽量香气不要跟原版变化太大；\n4、客户希望交版时间在7月15日前', '1', '3', 'B级项目', '1638968357988946,0549274114954944', '何家文,王鑫', '16455177663846080', '常晓爽', '[{\"fileName\":\"屈臣氏GL 7.2. ASW禁限用物质名单+7.3.ASW 过敏原政策.pdf\",\"timestamp\":\"Ahb5M5yVUFa8p1VwUEkw\",\"size\":1124685,\"secret\":null,\"fileId\":\"6d5c778f-258a-4b00-b3de-3f69f3a74440\",\"showSize\":\"1.1M\",\"fileClass\":\"iconBox pdfBox\"},{\"fileName\":\"微信图片_20260702111121_365_15.jpg\",\"timestamp\":\"XDawuMdmrtRuhXpLqaYy\",\"size\":2418611,\"secret\":null,\"fileId\":\"ea25319d-782e-409e-9bf2-fc23e257c428\",\"showSize\":\"2.3M\",\"fileClass\":\"iconBox imageBox\"}]', NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '1', '是', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-07-03 00:00:00', '170', NULL, NULL, NULL, NULL, NULL);
