INSERT INTO `w_bo_xs_projectmanage` VALUES ('2073974563284176897', '0', '0', '16466317325076496', '梁皓', '2026-07-06 11:37:23', '16466317325076496', '梁皓', '2026-10-09 13:34:09', '1', '2073974563502276610', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '2', 'XMBM202607060016', '1', '明确需求', '培蘑--百香果创香2.0 20260706', '2056240209187528706', '培蘑（上海）贸易有限公司', '寄样信息：上海慈竹路608弄3号楼1005 冷先生 17717022237\nSYP2043DSY 百香果香基\n客户需要新的创香，百香果的硫醚需要大量减少，以花香或草本香为主，搭配能感知到的百香果香气\n产品用于香水、无火、藤条、线香、滚珠油，香气感受可参考该品牌最新的芭乐栀子的感觉\n需要两个方向创香\n1：花香+百香果\n2：草本＋百香果\n需求价格：2000以内\n需要15%香水加香产品\n需求时间：7.24', '1', '1', 'S级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '1', '是', '', '', NULL, '', '', '2', '无要求', '4', '中国化妆品INCI', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, '客户确样后提供，有出口需求，需要81过敏原', NULL, '2027-07-31 00:00:00', '2000以内', NULL, NULL, NULL, NULL, NULL);
