INSERT INTO `w_bo_xs_projectmanage` VALUES ('2074421648517222402', '0', '0', '16466317325076496', '梁皓', '2026-07-07 17:13:57', '16466317325076496', '梁皓', '2026-07-07 17:14:25', '1', '2074421648739516418', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '2', 'XMBM202607070021', '1', '明确需求', '璞菏--无垢木与雪松、漫步间出口香水油仿香优化20260707', '2062847266191781889', '璞菏化妆品有限公司', '寄：周雯倩，15664110927，上海市奉贤区环城西路3111号8号璞菏（放入丰巢边上的蓝色专用框）\n客户有两款仿香需求，目标价格需要控制在200元/kg以下\n这是一款出口至东南亚的香水滚珠油产品，请在开发香精时做好相关的符合出口东南亚国家的相关法规风险把控\n下方是香型需求\n根据产品定位规划，产品以年轻时尚为调性，以亲民的价格服务东南亚年轻群体，满足年轻消费者们对沙龙香的追求，竞品及香型方向如下\n\n【竞品】\n1. “东南亚（泰国）当地” PANPURI\n2. “中国本地” 闻献\n\n【香型方向·沙龙香类型】\n1. 木质调：参考参考品牌 祖玛珑·无垢木与雪松\n前调：青苔芳香、肉桂\n中调：日本桧木、丁香、英国薰衣草\n后调：雪松、广藿香、冬加豆\n2. 花香调：参考品牌 馥马尔·漫步间\n前调：紫丁香、黄瓜\n后调：雪松、麝香\n\n实际需求：客户出口东南亚需注意出口法规是否符合标准\n香水油加香量为15~25%\n香水油溶剂为GTCC（辛癸酸甘油酯）\n需注意加香量以及溶剂适配性问题\n需要做仿香以及两个仿香基础上的加强版\n期望留香时长：6-8h\n需要每款寄样50g\n需求时间：7.17前寄出\n需求价格：200以内', '10', '2', 'A级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '16825006662777257', '齐钰', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '2', '无要求', '4', '中国化妆品INCI', '4,3,2', 'COA,SDS,IFRA', NULL, NULL, '客户确样后提供，需要81过敏原，需注意东南亚出口法规', NULL, '2027-07-31 00:00:00', '200以内', NULL, NULL, NULL, NULL, NULL);
