INSERT INTO `w_bo_xs_projectmanage` VALUES ('2077234903405023234', '0', '0', '050363634136321790', '逯柏松', '2026-07-15 11:32:49', '050363634136321790', '逯柏松', '2026-07-15 11:32:49', '1', '2077234903623122946', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202607150012', '1', '明确需求', '云檀修改-逐本（重要）', '1984130169849139201', '杭州舒彩网络科技有限公司', '云檀的香精需要在原来那款（花草玫语 LYP1696GLY）的基础上做调整，价格在800/KG以内。\n调整方向如下：\n1、改善现有尖锐白兰调引发的刺鼻、头晕、塑料感、汽油味等负面反馈，调整香味更柔和化\n2、保留原有白檀尾调，前调改为复合白花香（白兰+茉莉+栀子）\n3、调整后需保持与现有香调的基础轮廓一致，不能出现太大的差异\n4、需要口唇可用\n\n应用：卸妆油/卸妆膏\n价格：800以内\n时间：7月17前（尽量）\n香精：10ml\n备注：需要做两个版本，一个是原香精基础上优化，另一个尽量贴合修改要求的食品级版本\n寄样地址：\n李玲17370737282\n浙江省杭州市萧山区协和辉丰大厦A座2503', '100', '1', 'S级项目', '113845370124130976,050363634136321790', '彭佳庆,逯柏松', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2026-12-31 00:00:00', '800', NULL, NULL, NULL, NULL, NULL);
