INSERT INTO `w_bo_xs_projectmanage` VALUES ('2077586285773443073', '0', '0', '16466317325076496', '梁皓', '2026-07-16 10:49:05', '16466317325076496', '梁皓', '2026-07-16 10:49:05', '1', '2077586285966376961', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202607160004', '1', '明确需求', '璞菏--香水、手霜产品推荐&修改20260716', '2062847266191781889', '璞菏化妆品有限公司', '寄：周雯倩，15664110927，上海市奉贤区环城西路3111号8号璞菏（放入丰巢边上的蓝色专用框）\n根据客户提供三调进行大牌香氛推荐&修改，客户产品用于香水和手霜内\n每款需要2个样品\n需求1：\n前调:柠檬、苹果、黑加仑\n中调:菠萝、茉莉、广藿香\n后调:桦木、龙涎香、雪松、橡木苔\n\n需求2：\n前调:椰子、青柠、香柠檬、橘子\n中调:生姜、依兰、茉莉、木槿\n后调:朗姆酒、糖、麝香\n\n需求3：\n前调:香柠檬、柠檬、黑醋栗\n中调:菠萝、粉红胡椒、茉莉\n后调:桦木、广藿、麝香\n\n需求4：\n前调：青柠、苦橙、佛手柑\n中调：柏木、玫瑰、广藿香\n后调：愈创木、麝香\n\n需求5：\n前调:日本柚子精油0.20ml4滴\n佛手柑精油 0.15ml3滴\n青柠精油0.10ml2滴\n中调:阿曼绿乳香精油0.20ml4滴\n迈索尔檀香精油 0.20ml4滴\n香根草精油 0.15m13滴\n后调:没药精油0.10ml2滴\n橡苔原精0.05ml1滴\n琥珀原精0.15ml3滴\n这个就找相似的精油感仿香做修改即可\n\n需求6：\n前调:紫罗兰叶、豆蔻叶>青翠水绿、清凉甘草感\n中调:白松香、粉感花香>雾中睡莲，柔和淡雅\n后调:香草、小豆蔻>微甜温暖、木质沉稳\n需要寄样50g香精\n需求价格：200以内\n加香量预计15~20%\n可能存在出口需求，需注意法规以及5-mop物质！！！\n需求时间：最晚7.21寄出', '3', '3', 'B级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '2', '无要求', '4', '中国化妆品INCI', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, '确样后提供，客户产品用于香水，需要81过敏原，可能存在出口需求', NULL, '2027-07-31 00:00:00', '200以内', NULL, NULL, NULL, NULL, NULL);
