INSERT INTO `w_bo_xs_projectmanage` VALUES ('2080548395826515969', '0', '0', '16466317325076496', '梁皓', '2026-07-24 14:59:27', '16466317325076496', '梁皓', '2026-07-24 14:59:27', '1', '2080548396011028481', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202607240021', '1', '明确需求', '半亩花田--玫瑰花园升级20260724', '2043908791463821314', '山东半亩花田生物科技有限公司', '寄：上海办Gary\n优化HDB1113CHD 	玫瑰花园\n考虑到客户产品更新周期问题，目前先行品类更新优化迭代，抛弃原先框架进行新品选品优化\n根据客户产品研发思路选取近几年热门大牌香氛中的爆品玫瑰香作为base基底\n需要选3~4款大牌香氛进行优化，客户香精侧重于点：配伍稳定性、留香、香气强度，尽可能不变色\n增加玫瑰花的天然植萃感，需要添加我们能用于技术宣称的爆香和留香香基作为卖点\n需要同步测试稳定性，用我们内部base做加香测试，加香量1%\n需求价格：320以内，250以内最优\n产品内研完成后寄销售Gary\n需求时间：9.18', '200', '1', 'S级项目', '113845370124130976,16466317325076496,17127345845433575', '彭佳庆,梁皓,王晔', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '1', '是', '', '', NULL, '', '', '2', '无要求', '4', '中国化妆品INCI', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, NULL, NULL, '2029-07-31 00:00:00', '320以内，250以内最优', NULL, NULL, NULL, NULL, NULL);
