INSERT INTO `w_bo_xs_projectmanage` VALUES ('2085301461922598914', '0', '0', '16466317325076496', '梁皓', '2026-08-06 17:46:26', '16455177663846080', '常晓爽', '2026-08-10 16:13:23', '1', '2085301462073499650', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '5', 'XMBM202608060010', '1', '明确需求', '杭州云韵--超级种子--个护香型推荐20260806', '2085294814600876034', '杭州云韵品牌管理有限公司', '根据客户需求进推荐递样\n浮木苦橙、春绿、粉桃葡萄、天竺青提、气泡柑橘、昂蒂布之夏、青橙、杨桃\n产品用于沐浴露、洗发水、护发素\n后续客户会提供个护base加香后再寄出\n每款需要20~30g\n需求时间：8.10带上海办，确认后再寄样', '10', '2', 'A级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-08-31 00:00:00', '200~300', NULL, '2085295280546107394', 'Gia', 'Gia,15058351217,浙江省杭州市余杭区仓前街道创景路奥克斯时代未来之城5幢3001 Gia 15058351217\n\n', '8.10评香会带样品至上海办，后续销售安排寄出');
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2085305490958438401', '0', '0', '16466317325076496', '梁皓', '2026-08-06 18:02:27', '16455177663846080', '常晓爽', '2026-08-07 10:16:24', '1', '2085305491226779649', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202608060012', '1', '明确需求', '杭州云韵--松气--碧螺春、听雨、香水柠檬家居香氛新品推荐', '2085294814600876034', '杭州云韵品牌管理有限公司', '根据客户需求进行推荐递样\n需求1：西湖龙井\n同步可推荐茉莉花茶与单枞茶香推荐\n香气描述：主调有明显的西湖龙井茶香，最好是可以有点西湖龙井的特色豆香。感觉上比较淡雅，让人置身于茶室或者是置身于雨后茶园的感觉。\n\n需求2：香水柠檬\n根据已有香水柠檬Acord进行递样\n\n需求3：听雨\n根据客户描述推荐苔藓、壤香推荐，需要有国风感\n香气描述：闻起来让人想到晨露、雨天森林、雪松、山林微风、橡木苔。感觉很适配天青色，最好不要太过偏向于水生调\n\n产品首先应用于车载、香包、香氛喷雾\n后续品类拓展会应用于蜡烛无火以及个护产品内\n需要考虑产品的适配性与通用性\n需求价格：300以内\n需求时间：8.10上海办需要收到第一批推荐样品的香气确认', '5', '2', 'A级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-08-31 00:00:00', '300以内', NULL, '2085295280546107394', 'Gia', 'Gia,15058351217,浙江省杭州市余杭区仓前街道创景路奥克斯时代未来之城5幢3001 Gia 15058351217\n\n', '8.10评香会带样品至上海办，后续销售安排寄出');
