INSERT INTO `w_bo_xs_projectmanage` VALUES ('2086717277050228737', '0', '0', '16466317325076496', '梁皓', '2026-08-10 15:32:23', '17253690046572896', '周宇', '2026-08-11 09:59:59', '1', '2086717277213712385', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202608100018', '1', '明确需求', 'RE调香室--国风美食推荐', '1984130169421320194', '上海香淼贸易有限公司', '根据客户需求推荐国风美食调香气\n产品用于空清产品内需要注意ifra加香量\n销售建议10A类按20%添加量去确认，如无法达标烦请递样后告知销售\n需要花生  SYI183BSY\n红豆  YJA111BYJ\n甜粽子  LCP1062ALC\n如有其他优秀产品也可推荐\n需求价格：400\n需要寄样10g\n需求时间：8.21', '5', '4', 'C级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-08-31 00:00:00', '400', NULL, '2034161061568954370', 'Tera', '李萍,15620251599,天津市西青区杨柳青镇精成路12号\n\nTera,13482596955,上海市浦东新区耀元路58号3号楼中农投大厦 11C  RE调香室 Tera 13482596955\n\n', NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2086725202825170945', '0', '0', '16466317325076496', '梁皓', '2026-08-10 16:03:52', '17253690046572896', '周宇', '2026-08-12 12:01:07', '1', '2086725203051569153', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202608100022', '1', '明确需求', '上海筷予--东南亚文旅香型推荐20260810', '2086720458081685506', '上海筷予文化传播有限公司', '根据客户需求结合地方特色+文旅，对以下4个主题进行香型推荐\n1. 光与盐  --  海洋/清新/清爽   ----   但是不要太强的水生调，以清新干净冷感为主\n2. 南洋旧梦 --  草本/药香/清透  ----  斑斓叶的味道，可以带一点糯米，有药感的斑斓香\n3. 骑楼老宅 -- 木质/冷暖交织 ---- 有一种老宅子+老书籍的味道，但是要带一点暖或者冷的热带感\n4. 深白月夜 -- 白花/清冷/干净 ---- 鸡蛋花的味道，但是不要太直给。还是要偏一点冷感\n可在大牌香氛内寻找适合的推荐\n产品用于蜡烛+香氛喷雾，后续会用于车载\n每款出题需要推荐2~3支\n需要10%香水加香产品\n需求价格：200左右\n需求时间：8.13', '1', '4', 'C级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-08-31 00:00:00', '200左右', NULL, '2086721893083107329', '刘', '刘,18079791767,上海市长宁区江苏路，722弄4栋603 刘18079791767\n\n', NULL);
