INSERT INTO `w_bo_xs_projectmanage` VALUES ('2095072243141824514', '0', '0', '16466317325076496', '梁皓', '2026-09-02 16:52:02', '16455177663846080', '常晓爽', '2026-09-07 17:31:57', '1', '2095072243259170818', 'RUNNING', '运行中', '57435696', '香氛销售部', '3', 'XMBM202609020009', '1', '明确需求', '林里--橙子香型创香20260902', '2095046777513168897', '广州西帆文化创意有限公司', '客户下半年会出橙子主题饮品，并主推橙子周边香氛产品\n该款橙子饮品会添加百香果、香柠檬等元素\n产品用于香氛机内，180ml适配3~5滴香精/精油\n需要创香完成后同步测试\n产品需要做精油和香精两种形式\n\n纯精油橙子\n方向1：做橙子精油的稀释版本\n方向2：做做橙子复配精油（最好能添加果类精油，主要突出柑橘果香组分，往愉悦度高的方向调整，可添加橙叶类的绿叶元素或花香元素）\n需求价格：700元以内\n\n橙子香精\n方向1：做橙子+百香果+香柠檬的混合柑橘果香香氛）\n橙子为核心尽可能凸显\n方向2：在方向1的版本上做清透和绿叶清爽优化，提高愉悦度和接受度\n需求价格：300~400\n\n该款产品需要注意闪点问题\n目前该产品仅用于空间香氛，客户直接使用香精/精油添加入香氛机内，需确认法规添加量\n需求时间：最晚9.11需寄出', '10', '1', 'S级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-09-30 00:00:00', '300~400，700以内', NULL, '2095047365181296641', '杨曼霞', '杨曼霞,18565086913,广东省广州市天河区  丰兴广场-A座16层06A单元 杨曼霞 18565086913\n\n', NULL);
