INSERT INTO `w_bo_xs_projectmanage` VALUES ('2095769937028042754', '0', '0', '16466317325076496', '梁皓', '2026-09-04 15:04:25', '05035817329389', '刘畅', '2026-09-07 14:14:48', '1', '2095769937267023873', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202609040012', '1', '明确需求', 'KKV-果香个护产品推荐20260904', '2079403974493966337', 'KK集团', '【香精需求】\n人群：16～25岁年轻女性。\n价格：120～200元\n1️⃣磨砂膏：\nsku1果香：苹果＞葡萄＞蜜瓜=荔枝\nsku2果复合花香/水生调/茶香调 -  如葡萄茉莉、 荔枝水生、苹果大红袍等\n2️⃣身体精华露：\nsku1果香：苹果＞葡萄＞蜜瓜=荔枝\nsku2果复合花香/水生调/茶香调 -  如葡萄茉莉、 荔枝水生、苹果大红袍等\n3️⃣素颜霜：\nsku1主调需是果香， 建议- 葡萄＞蜜瓜=荔枝，香型建议同上可以复合花香or双果香\nsku2果复合花香/水生调/茶香调 -  如葡萄茉莉、 荔枝水生、苹果大红袍等\n\n最好能提供三个需求通用的香精，如果有香气表现优异但有品类限制须在品名后备注适用品类\n单一果香主题4个需求每个主题推荐3~5款\n复合果香主题3个需求每个主题推荐3~5款\n如需修改可分批寄样，优先寄库存推荐样品，再统一寄修改样品\n身体精华露加香量：预估0.8% \n素颜霜加香量：预估0.6%\n磨砂膏油溶体系加香量：预估1%\n需要提前确认法规\n该产品26年底需完成采购上市需求时间紧急\n需要香精10~20g\n需求价格：120~200\n需求时间：库存推荐9.8寄出，修改产品9.14寄出', '50', '1', 'S级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '05035817329389', '刘畅', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '1', '是', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-09-30 00:00:00', '120~200', NULL, '2079404102499930113', '赵怡', '赵怡,18586537710,东莞市南城街道袁屋边隐山路35号KK集团4楼 赵怡 18586537710 （收）\n\n', NULL);
