INSERT INTO `w_bo_xs_projectmanage` VALUES ('2099343784683753473', '0', '0', '16466317325076496', '梁皓', '2026-09-14 11:45:37', '05035817329389', '刘畅', '2026-09-14 17:32:09', '1', '2099343784876597249', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202609140008', '1', '明确需求', '旷世--图个心安系列藤条产品优化&推荐20260914', '1985593757705064449', '宁波香薰时代家居用品有限公司', '图个心安系列藤条香氛/车载/精油/香包等\n优先考虑藤条香氛选香。要求扩香好、爆发力和透发性不错，挥发速度尽量均匀，避免出现挥发到后面完全挥发不了的情况\n香味方向：\n1.柚好运：柚子叶+佛手柑+柑橘香气，适配柚子叶的概念：\n芦荟+柑橘\n2.有钱花：复合花香（可以考虑牡丹）等带有吉利寓意的花香；\n优先推荐符合需求的大牌香氛仿香优化\n3.接福禄：草本+绿叶，复合葫芦概念；需求价格：200以内：\n4.包行的：烤面包+奶香+谷物的低糖美食香，复合面包概念（香味意向：DH-R841572乖乖乳果，麻烦改版）\nJKC2390BJK	乖乖乳果\n注意：香精溶剂不要蜡烛常用溶剂，不要isopar\n需求价格：200以内\n需求时间：直接推荐的9.17出，需要优化修改的9.24前出\n需要香精50g', '5', '4', 'C级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '05035817329389', '刘畅', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-09-30 00:00:00', '200以内', NULL, '2036362719833079809', '吴千妤', '吴千妤,13252221512,浙江省宁波市海曙区气象路827号旷世智源工艺设计有限公司  吴千妤  13252221512\n\n', NULL);
