INSERT INTO `w_bo_xs_projectmanage` VALUES ('2099420806378409986', '0', '0', '16466317325076496', '梁皓', '2026-09-14 16:51:40', '05035817329389', '刘畅', '2026-09-15 15:13:23', '1', '2099420806533505026', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202609140023', '1', '明确需求', '旷世--布尔陶--蔬果园系列20260914', '1985593757705064449', '宁波香薰时代家居用品有限公司', '内销bt项目（目标年龄群体18-35岁女性），无火香氛，果蔬系列，价格200以内，要求扩香好，避免成品底部挥发液残留，挥发不掉。麻烦推荐下香味！\n香味方向：南瓜、香菜、欧芹。\n无火藤条香型需求\n需求1：南瓜\n气味设定：白天藤蔓和叶片带着水润的绿意与泥土味，夜里悄悄积攒糖分。\n最终飘出的，是一股软糯的、绵绵的、带着体温般的甜，不腻，像大地偷偷藏起来的温柔。\n\n需求2：香菜\n气味设定：连根带土拔出的完整香气，霸气清新、冲击力十足。\n\n需求3：欧芹\n气味设定：不是西餐里温驯的装饰，是带着:泥土和根须拔出来的野欧芹。\n气味比香菜更内敛，却更有韧劲，闷闷的、倔倔的绿意。\n\n需要每个方向至少推荐2款\n需要香精50g\n需求价格：200以内\n产品用于无火藤条需注意法规', '10', '2', 'A级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '05035817329389', '刘畅', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-09-30 00:00:00', '200以内', NULL, '2036362719833079809', '吴千妤', '吴千妤,13252221512,浙江省宁波市海曙区气象路827号旷世智源工艺设计有限公司  吴千妤  13252221512\n\n', NULL);
