INSERT INTO `w_bo_xs_projectmanage` VALUES ('2102291432663404545', '0', '0', '050363634136321790', '逯柏松', '2026-09-22 14:58:31', '05035817329389', '刘畅', '2026-09-23 09:39:46', '1', '2102291432868831234', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202609220012', '1', '明确需求', '宋朝香氛出口香型选香-', '1984130169790418945', '浙江宋朝臻选香氛有限公司', '他们需要在扫地机器里面加香，客户对香精有几点要求：\n1️⃣主要出口，香精符合多国法规，销售区域包括国内，欧洲，美国，东南亚，日本，韩国，俄罗斯，中东，以色列，土耳其，印度，澳洲\n\n2️⃣宠物友好型香精（宠物对一些香精很敏感）安全\n\n3️⃣需要耐高温70度，有些香精在扫地机器人里面会高温发生香气改变\n\n4️⃣香精稳定性要好，不变色。\n\n5️⃣香精也需要耐低温零下30度\n麻烦帮忙推荐匹配\n6：加香方式是香薰片，通过电加热扩散香气\n7：香精里面不要HCA（甲位己基肉桂醛）\n推荐5-8款\n应用：空间香氛\n价格；150以内\n香精：30ml\n时间：9月28寄出', '5', '1', 'S级项目', '050363634136321790,113845370124130976', '逯柏松,彭佳庆', '05035817329389', '刘畅', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2026-10-31 00:00:00', '150', NULL, '2069339637448429569', '马女士', '马女士,15988856039,杭州市滨江区长河街道塘子堰路159号笨鸟园区D幢6楼马女士15988856039\n\n', NULL);
