INSERT INTO `w_bo_xs_projectmanage` VALUES ('2108085915023818753', '0', '0', '050363634136321790', '逯柏松', '2026-10-08 14:43:43', '05035817329389', '刘畅', '2026-10-12 10:02:02', '1', '2108085915246092289', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202610080021', '1', '明确需求', '面膜香型开发-懿奈', '1984130168058171394', '懿奈（上海）生物科技有限公司', '产品：贴片面膜\n\n美白嫩肤功效，敏肌可用，人群年龄20-40岁之间\n香味目标：清新、淡雅、天然感强的青香木质调 / 木香芳香调。\n情绪联想：晨雾森林、雪后柏木、干净棉麻、沉静修护高级感。适合美白抗老线，不老气、不沉闷、不厚重、不药感。\n不要方向：不要年轻甜花香、不要浓烈香水感、不要药味重、不要酸味、不要粉感、不要皂感、不要廉价日化香。\n\n需要一款青香木质芳香调，味道参考：\n前调：柏树、竹叶、杜松子，冷绿微辛但不酸；\n中调：竹叶、绿叶、极淡白玉兰，清透柔软；\n后调：雪松、岩兰草、莎草、微量广藿香。干净、天然、沉静；\n\n整体要清新淡雅、修护和抗老高端感，香味低强度、贴肤、干净、舒适，敷面时若有若无，揭下后只留一点淡淡的香味。\n\n商业参考：闻献 杉间淡香精版\n香型推荐2-3款\n\n价格：350\n香精：10ml\n时间：10月10号寄出\n寄件地址：蓝蓝 13971511226 上海市黄浦区淮海中路2-8号（淮海中路西藏南路）兰生大厦20楼', '1', '3', 'B级项目', '050363634136321790,113845370124130976', '逯柏松,彭佳庆', '05035817329389', '刘畅', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2026-10-31 00:00:00', '350', NULL, '2108085551079866370', '蓝蓝', '蓝蓝,13971511226,上海市黄浦区淮海中路2-8号（淮海中路西藏南路）兰生大厦20楼\n\n', NULL);
