INSERT INTO `w_bo_xs_projectmanage` VALUES ('2108104065471725570', '0', '0', '05035817437137', '宣二鹏', '2026-10-08 15:55:51', '17804235042843764', '陈赛', '2026-10-08 16:54:01', '1', '2108104065647861762', 'SUCCESS_END', '成功结束', '1055268928', '日化销售1部', '3', 'XMBM202610080029', '1', '明确需求', '红卫-香皂木质香东方香20261008', '1984130174001500162', '包头市红卫日用化工有限公司', '香皂项目：\n1.客户需要木质风格，香东方香型\n2.香精价格190元-200元/公斤，尽量做到不含溶剂或含有效溶剂\n3.香精各需要10克\n4.带送样单，送样单：型号+名称+香气描述+精油添加+灵感来源（大牌仿香）\n5.推荐3-5种\n6.香皂加香量1.5%\n7.尽可能做到不变色，如果变色送样单请注明变色因素\n8.不含禁用和现用原料\n9.同步质检部配方，需要SDS,IFRA，COA ，需求时间寄出样品后三个工作日内。\n10.预计客户收到时间10月16日前\n备注：先寄样品，同步做稳定性测试', '-', '1', 'S级项目', '05035817437137,17400514601408872', '宣二鹏,于姗姗', '17804235042843764', '陈赛', NULL, NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '1', '是', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-09-29 00:00:00', '-', NULL, '2087446166613512194', '胡少康', '胡少康,18147223870,包头市东河区铝业园区红卫日用化工有限公司\n\n', NULL);
