INSERT INTO `w_bo_xs_projectmanage` VALUES ('2108860631825235969', '0', '0', '02461210300720808373', '余鹏程', '2026-10-10 18:02:10', '17804235042843764', '陈赛', '2026-10-12 09:08:41', '1', '2108860631980400641', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202610100012', '1', '明确需求', '青岛伊特酒店皂香精推荐26-10-10', '2108859959419584514', '青岛伊特丰源贸易有限公司', '请推荐以下四种香精：\n青苹果香精（澳洲青苹香型）：洗涤剂级，100% 纯浓缩香精\n载体溶剂：丙二醇（MPG）或邻苯二甲酸二乙酯（DEP）\n高热稳定性与表面活性剂稳定性：适用温度 60℃～80℃\n可完全溶于阴离子表面活性剂。\n\n红苹果香精（红蛇果香型）：酒店皂用级 / 化妆品级\n100% 纯浓缩香精，耐碱性（pH 7–11），符合 IFRA 第 9 类规范。\n\n雪松岩兰草复配香精：酒店皂用级、化妆品级\n100% 未稀释原液，**无香兰素**，碱性条件下稳定。\n\n檀香小豆蔻香精：酒店皂用级 / 化妆品级\n100% 未稀释原液，香气醇厚乳脂感，**无香兰素，不变色*\n出口非洲，味大便宜最好，不用太多高级感，价格控制在150以内\n10.14之前寄出', '5', '4', 'C级项目', '02461210300720808373', '余鹏程', '17804235042843764', '陈赛', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-10-10 00:00:00', '150', NULL, '2108860096988561409', '王霞', '王霞,18954221560,山东省青岛市李沧区金水路1581-12\n\n', NULL);
