INSERT INTO `w_bo_xs_projectmanage` VALUES ('2109479532393119745', '0', '0', '1638968357988946', '何家文', '2026-10-12 11:01:27', '16825006662777257', '齐钰', '2026-10-12 11:13:37', '1', '2109479532657336322', 'SUCCESS_END', '成功结束', '1055369916', '日化销售2部', '3', 'XMBM202610120006', '1', '明确需求', '嘉美方总    够姜香水', '2059623163884429313', '香水博主  方生', '这个项目麻烦给到上海调香师做，做好一版后可以先给乐总闻一下，乐总会给部分意见，然后没问题再寄出给客户。\n主题:够姜，在广东话就是\"有胆\"\"有种\"的意思。\n想法:整体的味道希望是能够闻起来清新提神的感觉，姜是主要的味道，上次那个沙姜精油就挺不错的，不会太冲；\n可以加一些姜花，寓意：不仅够姜，钱也要够花；同时也可以有一点橙子的味道，寓意大吉大利，如果可以的话，也可以再加一些水仙花的感觉，因为水仙花是广东春节特有的花香\n留香要求：这支香不要出现甜腻，沉闷跟脂粉感，皮肤留香时间最好是能够做到5~8小时\n产品：香水\n价格：1000-3000（可以不用太考虑价格问题）\n数量：50克', '1', '3', 'B级项目', '1638968357988946,0549274114954944', '何家文,王鑫', '16825006662777257', '齐钰', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-10-12 00:00:00', '1000-3000', NULL, '2059623287356350465', '方生', '方生,18122445258,广州市白云区均禾街新石路114号 嘉美智造园F栋二楼\n\n', NULL);
