INSERT INTO `w_bo_xs_projectmanage` VALUES ('2110218275039199233', '0', '0', '16855125875633810', '邢芬', '2026-10-14 11:56:57', '16275212368889684', '赵文雅', '2026-10-14 12:04:16', '1', '2110218275345358850', 'SUCCESS_END', '成功结束', '1009466484', '销售服务部', '3', 'XMBM202610140009', '1', '明确需求', '美蜜找香-身体喷雾和房间喷雾出口美国-1014', '1985593757684092930', '浙江美蜜科技有限公司', '做身体喷雾和房间喷雾出口美国\n- 尤加利留兰香：融合尤加利精油，清脑醒神；搭配留兰香精油，提振情绪。\n- 薰衣草香草：薰衣草精油营造静谧舒缓感，香草原精安定心绪。\n- 柑橘生姜：甜橙精油唤醒活力，生姜精油刺激感官、焕发元气。\n- 尤加利清茶：尤加利精油帮助放松，茶萃取物舒缓不安的情绪。\n- 黑洋甘菊：配方主打舒缓，助力养成安稳的睡眠习惯。\n- 复古玫瑰：玫瑰精油调香，唤起自爱之心，接纳自我情绪。\n这些香味本周五一定要帮我寄出来', '-', '4', 'C级项目', '16855125875633810,02461210300720808373', '邢芬,余鹏程', '16275212368889684', '赵文雅', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-10-14 00:00:00', '230', NULL, '2033448164891017217', '黄志军', '黄志军,18057925210,浙江省金华市义乌市义亭镇相宜路86号\n\n', NULL);
