INSERT INTO `w_bo_xs_projectmanage` VALUES ('2113158043007959041', '0', '0', '16466317325076496', '梁皓', '2026-10-22 14:38:33', '05035817329389', '刘畅', '2026-10-28 16:18:25', '1', '2113158043226038273', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202610220023', '1', '明确需求', 'Hipitag--柠檬海盐口腔香型创香20261022', '2113154444584534018', '上海葡十科技有限公司', '蓝色系列口腔产品\n不建议大量添加薄荷，薄荷仅辅助凉感，香气主体必须是柠檬 + 椰子 + 海盐！！！！！！！\n产品用于：牙膏、口喷、漱口水\n柠檬檬海盐为主要记忆点，增加椰奶风味提升独特性，但是奶味不要抢味，整体来说是蓝色系列的记忆点，走的是海滩沙滩阳光海浪的感受\n香型定位：清新海洋椰柠调\n前调：柠檬\n中调：椰子\n尾调：海盐\n目标风格：干净通透、不甜腻、无厚重奶感\n稳定性： \n适配基质：牙膏（含水、摩擦剂、发泡体系）、醇基口喷、含水漱口水；\n高低温测试：45℃、-15℃循环，3 个月，不褪色、不析油、不沉淀、香型不变调；\n耐酸碱：适配口腔产品 pH 区间 5.0–8.5，香精不氧化变色（产品为蓝色料体，香精不能导致蓝料体发黄 / 变色）。\n光敏性：无强光敏原料，产品可常温储存。\n低致敏，优先低刺激原料；不含禁用致敏香精组分（按国标标注过敏原）。\n.交付 2 版备选： \n版本 A：标准版（推荐主选，按本 brief 香调比例）\n版本 B：微调版（海盐感更突出，椰子感减弱，作为备选对比）\n\n需求时间：10.30\n需求价格：500以内', '3', '2', 'A级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '05035817329389,17906565377856558', '刘畅,张婧悦', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-10-31 00:00:00', '500以内', NULL, '2113154831798484993', 'Jenny', 'Jenny,13162972631,上海市静安区云欣路200号亚龙创业园7号楼708室  Jenny 13162972631\n\n', NULL);
