INSERT INTO `w_bo_xs_projectmanage` VALUES ('2113218112055656449', '0', '0', '16466317325076496', '梁皓', '2026-10-22 18:37:14', '17906565377856558', '张婧悦', '2026-10-23 15:19:27', '1', '2113218112252764162', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202610220033', '1', '明确需求', '蜜丝婷--展会产品推荐20261022', '2113215418687537153', '上海蜜丝婷市场营销服务有限公司', '根据客户选中展会产品进行推荐\n个护线：\nSYA2521BSY 听风眠\nLYP2112BLY 夜雨峡湾\nSYB1580HSY 陈皮京柚\nZXB2037AZX 百香长相思\nLYP2239FLY 木姜子雪酪\nLYP982BLY 奇异果奶黄\nJKB2491ADH 霜落乌梅\n需要提供20~30g\n\n香水线\nDXP2382ADX   取暖\nFLP2014BFL   迁徙\nLYP2348ALY   1914\nJKP2428AJK   礼物\nSYP2459ASY  700年后的空气-瓦力\nLCP2179ALC  700年后的空气-伊娃\n\n每款提供10g香精以及20%香水加香产品', '1', '4', 'C级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '17906565377856558,05035817329389', '张婧悦,刘畅', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-10-31 00:00:00', '无', NULL, '2113216499408683010', 'Hannah', 'Hannah,17315531026,上海市闵行区虹桥镇科技绿洲4期3号楼11层 Hannah 17315531026\n\n', NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2113225011052396545', '0', '0', '16466317325076496', '梁皓', '2026-10-22 19:04:39', '05035817329389', '刘畅', '2026-10-28 18:14:11', '1', '2113225011362750465', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202610220034', '1', '明确需求', '至外--城市系列香水香氛创香20261022', '2113219251622887425', '上海元物未来生物科技发展有限公司', '需求1：提供客户展会选中产品\nFLP2431AFL 原野群鸣\n\n需求2：城市系列特调-武汉&郑州两个城市系列\n武汉\n方向1：江木与汗\n雪松丝柏为主题核心\n增加海洋矿物感需要一些海盐感\n尾调增加一些麝香，增加海洋流动感\n一定不能甜，主题还是以清爽感为表现\n\n方向2：落日码头\n前调：柚子皮/陈皮+海盐模拟江风的感受\n中调：苔藓+土壤感（类似胡萝卜籽或香根草的壤香）\n尾调：香根草+膏甜\n\n郑州\n方向1：五色土\n陶土与矿物感为核心进行创香\n需要后土壤的厚重感，另外可以增加一些粉尘感\n以香根草叠加些许广藿\n前中调需要乳香和焚香感\n\n方向2：河沉积\n前调需要干燥谷物感（类似小麦或麦麸）\n中调需要矿物感与烟草灰尘\n尾调以琥珀膏甜收尾\n\n需求3：祛味喷雾\n方向1：柑橘木质\n香柠檬+草本绿叶（鼠尾草/迷迭香）+雪松/香根\n需要有洁净感联想\n\n方向2：绿木与矿物\n类似大地的矿物感+无花果叶/番茄叶+尾调苔藓、雪松、些许广藿\n\n方向3：洁净木质\n皂感伪体香（类似卡朗-自己或隐衫之欲）+开司米木/愈创木的干燥粉感木质\n\n需求价格：城市系列1000左右，祛味喷雾500以内\n需求时间：10.30\n创香完成后销售确认是否需要线下拜访\n城市系列需要20%香水加香\n祛味喷雾需要10%香水加香', '5', '2', 'A级项目', '16466317325076496,17127345845433575,113845370124130976', '梁皓,王晔,彭佳庆', '16455177663846080,05035817329389,17906565377856558', '常晓爽,刘畅,张婧悦', '[{\"fileName\":\"2026-秋冬至外画册.pdf\",\"timestamp\":\"7iUbui4ag4C9hakKBEMN\",\"size\":23585256,\"secret\":null,\"fileId\":\"826ed923-b845-4def-9e0d-c2a6aa15c05c\",\"showSize\":\"22.5M\",\"fileClass\":\"iconBox pdfBox\"}]', NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-10-31 00:00:00', '城市系列1000左右，祛味喷雾500以内', NULL, '2113219696059727873', '文木', '文木,13777431504,上海市杨浦区黄兴路221号T1栋2楼221室 文木 13777431504\n\n', NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2113307393742848002', '0', '0', '02461210300720808373', '余鹏程', '2026-10-23 00:32:01', '16275212368889684', '赵文雅', '2026-10-23 09:20:43', '1', '2113307394036424705', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202610230001', '1', '明确需求', '河南香霁【桂花B】香精调整26-10-23', '2099428546614120449', '新蔡县香霁商贸有限公司', 'DH-U071651	桂花B\nLYP1125ALY\n客户目前已采购此香精用于盘香，但希望在成本不变的基础上，强化桂花的天然花香感，可适当减少其他原料用量；\n因客户极端追求还原桂花的花感，改版香精需在做完加香测试后寄出；\n加香测试目的：验证点燃后的桂花的花香是否明显\n样品请注意标注“改进版”', '25', '3', 'B级项目', '02461210300720808373', '余鹏程', '16275212368889684', '赵文雅', NULL, NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-10-23 00:00:00', '200', '2%', '2099428788910673922', '韩旭（临时）', '韩旭（临时）,18071139715,河南省驻马店市新蔡县 月亮湾街道 产业聚集区文化路军旅时代院内4号厂房办公室\n\n', NULL);
