INSERT INTO `w_bo_xs_projectmanage` VALUES ('2117076832284033025', '0', '0', '04476151361985', '何佳', '2026-11-02 10:10:25', '16275212368889684', '赵文雅', '2026-11-03 14:01:31', '1', '2117076832489529345', 'SUCCESS_END', '成功结束', '1009466484', '销售服务部', '3', 'XMBM202611020005', '1', '明确需求', '11.2源达荔枝推荐', '1984130165050855425', '天津源达日化股份有限公司', '香精需求：荔枝香型，用于香氛除湿袋，偏油性、可浸润EVA粒子。\n香气基调：清新自然荔枝果香，拒绝厚重甜腻的蜜甜果肉款。\n使用场景：衣柜+浴室高湿环境，优先选清爽、不易闷浊的香型。\n请按下面4个方向分开送样：百香果有没有新的香型？他那边还提提出了百香果，但是优选荔枝\n\n1. 清新纯水润荔枝（单香，汁水感，低糖）\n\n2. 荔枝+绿茶/乌龙（压甜，干净通吃衣柜、浴室）\n\n3. 荔枝+佛手柑（少量柑橘提亮，水灵清爽）\n\n4. 荔枝+海盐/淡白麝香（洁净凉感，浴室抑味效果好）\n\n以上仅为参考方向，不限于这几款。也麻烦贵司结合当下香氛潮流，同步推荐你们市场反馈好、热销的荔枝系香型，多谢！', '20000', '3', 'B级项目', '04476151361985', '何佳', '16275212368889684', '赵文雅', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-11-02 00:00:00', '150', NULL, '2034161060126113794', '戚慧芳', '戚慧芳,15822125457,天津西青区微电子工业区微二路6号\n\n', NULL);
