INSERT INTO `w_bo_xs_projectmanage` VALUES ('2117498578401214465', '0', '0', '16466317325076496', '梁皓', '2026-11-03 14:06:17', '05035817329389', '刘畅', '2026-11-06 15:09:38', '1', '2117498578598322177', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202611030009', '1', '明确需求', '弗止--鸣潮角色香织物喷雾20261103', '2055159516269338626', '雪叶（上海）创意设计有限公司', '鸣潮角色香氛喷雾\n共三个人物香氛\n每个需求需要推荐3款，可在推荐上修改更接近客户需求内容\n上线预计在初夏，香气需要偏清爽\n需注意10A类法规加香量！！！！\n\n需求1：景燃\n参考三调\n前调：佛手柑 杜松子 粉红胡椒\n中调：马黛茶 紫罗兰叶 快乐鼠尾草 梨\n后调：雪松 白麝香 绿色皮革 岩兰草\n市场产品参考\nMEMO 爱尔兰皮革\n\n需求2：爱弥斯\n参考三调\n前调：梨 橙花 香柠檬 粉红胡椒\n中调：玫瑰 牡丹 榛子 铃兰\n后调：开司米木 雪松 杜松 琥珀\n市场产品参考\n馥阁 我可否将你比作一个夏日/creed\n银雾玫瑰\n\n需求3：绯雪\n前调：柚子 杜松子\n中调：醛 樱花 小苍兰 雪\n后调：日本桧木 白麝香 雪松 一点点点点\n点藏红花（需要一点辛辣)\n市场产品参考\n安南之香\n樱吹雪\n\n需求4：心\n前调：甜橙 荔枝 粉红胡椒 秦艽\n中调：白茶 玫瑰 鸢尾花 焚香\n后调：冷杉 雪松 琥珀 白麝香\n市场产品参考\n妩媚版本的雪白龙胆\n\n主要是做织物香氛和香氛挂件，需要考虑舒适程度以及扩香效果\n游戏定位：本身是男性向ml（master love）二游，游戏整体风格（包含剧情、女npc的服设\n等）还是偏向于男性受众。\n玩家性别比：男女比约为9：1\n考虑到受众，香气最好是稍微中性一点的\n需求价格：200~300\n需要15%香水加香产品\n需求时间：11.20', '3', '2', 'A级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '05035817329389,17906565377856558', '刘畅,张婧悦', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-11-30 00:00:00', '200~300', NULL, '2055159748134658049', 'jiojio', 'jiojio,15178065377,上海市静安区江场路1447号云芯科创中心T1号楼19楼DO事业部 jiojio，15178065377\n\n', NULL);
