INSERT INTO `w_bo_xs_projectmanage` VALUES ('2118256094349344769', '0', '0', '16466317325076496', '梁皓', '2026-11-05 16:16:23', '05035817329389', '刘畅', '2026-11-17 18:56:23', '1', '2118256094504509441', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202611050026', '1', '明确需求', '萨若之感--新品开发推荐20261105', '2082372966535892993', '上海萨珞斯商业有限公司', '客户产品用于环境香氛喷雾内\n\n需求1：仿香推荐\n推荐客户对标仿香过的产品\n观夏 苦尽橙（柑橘木质焚香）\n观夏 111号孤岛（茶香东方木质）\n观夏 南音芭乐（冰凉果香×桂花木质）\n蓦刻MO MAEK 南国芭乐（高还原果实）\n观夏 颐和金桂（桂花×桃果×琥珀麝香）\nDiptyque 杜桑（清冷晚香玉×海洋调）\n五分之山 杏与青藤（杏子果香木质）\n选择已仿香过的产品推荐即可\n需求价格：200~500\n\n需求2：新品开发推荐（可做优化）\n方向1：优先级高的产品\n海岸柑橘 / 香柠檬苦橙\n沉檀 / 焚香（东方木质）\n清茶 / 白茶\n雾感鸢尾\n干净皂感 / 白麝香（伪体香）\n现代沉香（绿意/香草调）\n焚香柑橘树脂（对标AENTOS坤元）\n乌木普洱·茶×焚香（对标屋闻大树）\n桂花（东方甜花）\n露水栀子（清新白花）\n铃兰（清幽山谷百合）\n改11款未高优先级开发主题需要重点挑选合适的\n每个主题需要推荐3款样品，可以库内有的优先寄出\n需求价格：200~1000\n\n无花果（绿叶向）\n柔和木质麝香（雪松+白麝香）\n地域植物志（地中海/岛屿）\n药感 / 根茎与树脂\n\n方向2：优先级次级产品\n无花果（绿叶向）\n柔和木质麝香（雪松+白麝香）\n地域植物志（地中海/岛屿）\n药感 / 根茎与树脂\n草本薄荷绿意（对标AENTOS生）\n冥想木质花香（对标AENTOS土也）\n烟熏篝火木质（对标卯时卯刻蜡烛）\n暖甜东方木质（对标屋闻零陵香豆）\n柚子叶（青绿草本）\n茉莉清茶（听泉茉莉向）\n兰花（东方馥郁兰）\n该系列主题推荐1~2款即可\n需求价格：200~500\n需要备注对应选品主题\n\n高优先级产品需要15%香水加香产品！！！！！！！！！！！\n需确认4类或10A类加香量\n需求时间：11.20全部选出寄出，高优先级需要11.13寄出', '2', '4', 'C级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '05035817329389,17906565377856558', '刘畅,张婧悦', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-11-30 00:00:00', '200~1000', NULL, '2082373331427758081', '马曼曼', '马曼曼,18701794453,上海市普陀区长寿路街道长寿路189号联合办公7楼712-1 马曼曼 18701794453\n\n', NULL);
