INSERT INTO `w_bo_xs_projectmanage` VALUES ('2118643231196356609', '0', '0', '02461210300720808373', '余鹏程', '2026-11-06 17:54:43', '16825006662777257', '齐钰', '2026-11-09 10:11:05', '1', '2118643231422914561', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '3', 'XMBM202611060010', '1', '明确需求', '北京尚潮香膏香精推荐26-11-06', '2061985574683631617', '北京尚潮创意纪念品开发有限公司', '1、香膏品类-玫瑰香膏\n·香调参考：祖玛珑 红玫瑰（Red Roses）、保罗史密斯 玫瑰之约（Paul Smith Rose）、梵诗柯香 盛放玫瑰（À la rose，MFK）、雅芮 格拉斯玫瑰（Rose de Grasse Pour Filles）、迪奥 玫舞轻旋（Miss Dior Rose N\'Roses）\n·香味描述：轻柔花香，主香调，玫瑰花香\n·目标人群：：女性，送礼向\n·需求量：5kg\n·价格：300-500/公斤 品质可以更好些\n\n\n2、香膏品类-爱心形香膏\n·香味描述：木质调：柠檬、柑橘、桂花、；花香调+绿调：香柠檬、玫瑰、茉莉、沉香、琥珀、白麝香；\n·目标人群：：女性，送礼向\n·需求量：5kg\n·价格：300-500/公斤 品质可以更好些\n\n4、工厂推荐香：我司新品香型推荐3-5款\n\n注意！请在样品标签上注明属于哪个分类，如“玫瑰香膏”、“爱心形香膏”、还是“工厂推荐香”\n1号需求、2号需求尽量按客户提供的每个元素对应一款香精', '10', '4', 'C级项目', '02461210300720808373', '余鹏程', '16825006662777257', '齐钰', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-11-06 00:00:00', '400内', NULL, '2061985820599869441', '章迈', '章迈,15532315641,北京市 东城区 详细地址:科林大厦A座5层\n\n', NULL);
