INSERT INTO `w_bo_xs_projectmanage` VALUES ('2119720821990506498', '0', '0', '050363634136321790', '逯柏松', '2026-11-09 17:16:41', '05035817329389', '刘畅', '2026-11-17 19:29:10', '1', '2119720822212890625', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '5', 'XMBM202611090035', '1', '明确需求', '杜鹃品牌香创香-九色花', '2035976146054529025', '上海九色花品牌管理有限公司', '新项目可以开始[呲牙]首批目标是30ml x 1000瓶。\n还是花香为主，果香调点缀，木质收尾，整只香，要花香里面叠加暖感，但还保留清凉感。\n春游时，风里面飘来花香的氛围感，不是粉感。像是清晨花瓣带露珠那种，清新的花香。\n粉色、红色的花，杜鹃主题。不追求写实，嗅感是花香、暖感、甜感。\n\n新香的安全标准参考欧盟化妆品法规及欧盟CLP标准。\n偏女香\n\nKG单价控制在600左右，预计（不晚于）2027年春节前完成备案，大货预计在2027年2月底前。\n应用：香水\n价格：600\n时间，11月底寄出\n香精：15ml；加香产品15%\n\n上海市浦东新区周浦镇周东路458弄7号101室\n祁奕 15821146928', '1', '4', 'C级项目', '050363634136321790,113845370124130976', '逯柏松,彭佳庆', '17906565377856558,05035817329389', '张婧悦,刘畅', NULL, NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2026-12-30 00:00:00', '600', '15%', '2119720955545534465', '祁奕', '祁奕,15821146928,上海市浦东新区周浦镇周东路458弄7号101室\n\n', NULL);
