INSERT INTO `w_bo_xs_projectmanage` VALUES ('2120381326602158082', '0', '0', '16466317325076496', '梁皓', '2026-11-11 13:01:18', '16466317325076496', '梁皓', '2026-11-11 13:01:25', '1', '2120381326988120065', 'RUNNING', '运行中', '57435696', '香氛销售部', '2', 'XMBM202611110014', '1', '明确需求', '毋名--个护按摩油推荐20261111', '2120372605507485697', '西安毋名商贸有限责任公司', '根据客户需求进行推荐\n客户产品用于按摩油内，目前处于产品设计初期\n先提供一些样品给到客户作为灵感\n客户品牌香气偏中式，有一个核心原料作为主题，类似aesop或le labo\n客户香气有两个需求\n需求1：缓解肌肉酸痛概念\n该类核心天然原料宣称需要具有抗炎属性\neg：薰衣草、洋甘菊、乳香、尤加利等\n需要纯精油版本推荐1~2款\n香精版本推荐3~5款\n偏天然草本感重（目前客户最新产品是乳香香气，尽可能规避一下乳香做主要核心元素）\n\n需求2：舒缓助眠概念\n该类天然原料普遍拥有镇静类功效\neg：香柠檬、雪松、香根草、檀香等\n需要纯精油版本推荐1~2款\n香精版本推荐3~5款\n\n需求价格：香精类：350，纯精油类：500~800\n需要标注香精和精油\n需要提供香水油类加香产品给到客户，加香量1%需重点关注香型遮盖力\n需求时间：11.18', '3', '2', 'A级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '05035817329389,17906565377856558', '刘畅,张婧悦', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-11-30 00:00:00', '香精类：350，纯精油类：500~800', NULL, '2120374624972587010', '邢女士', '邢女士,18092425026,陕西省西安市雁塔区高新一路15号中航大厦6楼，邢女士18092425026\n\n', NULL);
