INSERT INTO `w_bo_xs_projectmanage` VALUES ('2120724447349325825', '0', '0', '16466317325076496', '梁皓', '2026-11-12 11:44:44', '16466317325076496', '梁皓', '2026-11-12 11:44:50', '1', '2120724447617847297', 'RUNNING', '运行中', '57435696', '香氛销售部', '2', 'XMBM202611120019', '1', '明确需求', '其里--27年香水-气息手记新品开发20261112', '1984130169731698689', '上海白一则生物科技有限公司', '1、气味风格：春夏感、浅凉、干净、易穿、贴肤伪体香\n2、共计6只香型，每只需要最少一个“春夏应季或时令”气味，如原料为季节限定的水果或植物\n3、香精成本需控制在1000元左右\n4、希望合作更多的女性调香师\n\n需求1：植物学家、女诗人、她们的诗\n冷感绿叶方向\n\n需求2：青瓜备忘录\n青瓜气泡感香水可准备：LYC1555DLY	雨林气泡\n参考产品：Youssoful 青提无花果、Dusita 灵魂挚友、Maison Margiela 微醺后、Nonfiction Green Grape 青提气泡水、Tamburins 雨后青果\n\n需求3：空无一物\n客户意向产品类似：暴雨宿山\n杜松清新、绿意、土壤、苔藓、湿润\n参考产品：le labo 19、Pleuvoir 清晨土壤 Morning Soil\n\n需求4：白日亚麻、光之子\n伪体香：卡朗-自己LYP2175BLY\n参考产品：配枪朱丽叶 隐杉之欲、Forment 云绒之拥 cotton hug、LOE 白衬衫 White shirts\n\n需求5：野蔷薇日记、洛丽塔\n玫瑰主题水润玫瑰\n参考产品：Tamburins 落日霞光、Nonfiction 春日蔷薇 Rosy Side、Diptyque 玫瑰之水、Masion Francis Kurkdjian 一支玫瑰、Byredo 初\n生玫瑰、Nonfiction Rosy Side 蔷薇侧\n\n6、冷空气\n可准备极地：FLC2010FFL或其他杜松冷感香气\n参考产品：Nonfiction 米色诗篇、Tamburins Solace 一丝慰藉、Forment 浴后清冽 Fresh Shower、Byredo 超级雪松 Super cedar、\nNonfiction Grain 谷间微风\n\n该新品线先准备1~2款现有产品，客户11.17线下拜访根据实际需求进行优化或创香\n需要20%香水加香产品\n需求时间：11.16\n需求价格：1000\n\n样品暂定销售自提，后续优化版递样工单地址', '3', '2', 'A级项目', '16466317325076496,113845370124130976', '梁皓,彭佳庆', '05035817329389,17906565377856558', '刘畅,张婧悦', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-11-30 00:00:00', '1000', NULL, '2099353789432582145', '不是可颂', '不是可颂,13564612878,上海市徐汇区龙华中路596号 绿地中心A座506室 不是可颂 13564612878\n\n', NULL);
