INSERT INTO `w_bo_xs_projectmanage` VALUES ('2122569110423224321', '0', '0', '050363634136321790', '逯柏松', '2026-11-17 13:54:46', '050363634136321790', '逯柏松', '2026-11-17 13:55:24', '1', '2122569110574305282', 'RUNNING', '运行中', '57435696', '香氛销售部', '4', 'XMBM202611170008', '1', '明确需求', '暖暖Nikki香水产品开发-御梵', '1985593757503737857', '湖州御梵未来式供应链有限公司', '暖暖(Nikki)是叠纸游戏(Papergames)打造的头部女性向换装IP，主角叫暖暖(Nikki)，搭档是橘猫大喵(Momo)，世界观\n舞台主要是奇迹大陆(Miraland)，核心主题:穿搭美学、自我表达、搭配冒险。\n系列作品顺序\n1.《暖暖的换装物语》(2012):初代，暖暖IP起点\n2.《暖暖环游世界》(2013):二代，环游世界旅行换装\n3.《奇迹暖暖》\n(2015):三代，2D，奇迹大陆七国剧情，国民级换装手游\n4.《闪耀暖暖》\n(2019):四代，3D换装，高质感建模\n5.《无限暖暖》:最新，开放世界换装冒险游戏InfoldGam...\nIP定位&衍生\n核心标签:少女、时尚穿搭、审美、幻想、治愈;全球海量女性，IP注册用户超2亿\n香型方向：\n1：无限暖暖果香调(桃子、草莓、浆果....)雪花、冬季氛围的味道\n2；闪耀暖暖西普调(橡木苔、佛手柑、广藿香白花香调(茉莉、栀子花、晚香玉、铃兰...)*优先西普调\n3：奇迹暖暖花香调(玫瑰)醛香调(肥皂、洁净白衬衫....)芳香调(鼠尾草...)\n*首推玫瑰方向的，但是调子不要太浓烈，整体需要往清新调方向\n\n应用：香水\n价格：500\n时间：11月25号\n每个方向提供两款香型\n要求女性调香师，需要配方保密', '5', '1', 'S级项目', '050363634136321790,113845370124130976', '逯柏松,彭佳庆', '17906565377856558,05035817329389', '张婧悦,刘畅', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2026-12-31 00:00:00', '500', NULL, '2034161059991896066', '罗奇', '罗奇,13915568594,江苏省苏州市相城区南天成路24号傲英大厦505室 罗奇 收 电话13915568594\n\n', NULL);
